-- =====================================================================
-- SIGAF · RECARGA de COMPRA EMERGENTE desde la cedula (hoja cb)
-- Reemplaza TODAS las facturas del capitulo 'Compra Emergente' por las
-- 915 de la cedula. Transaccional: si algo no cuadra, no aplica nada.
-- Estatus: PAGADA->pagada, TP->enviada OOAD, SE->en servicio, DEV->devuelta.
-- Pasivos (col 'PASIVO') -> anio 2025. Filas sin cuenta -> cuenta dominante
-- del proveedor (10 filas). Excluidas (1): FF AJUSTE $69742.34
-- Correr en el SQL Editor de Supabase.
-- =====================================================================

begin;

create temp table stg_ce (folio text, importe numeric(14,2), proveedor text, cuenta text, mes int, anio int, mes_ej int, anio_ej int, gen text, fir text, ped text, cr text, oc text, pasivo boolean) on commit drop;


-- Alta de proveedores faltantes

-- Validaciones: toda cuenta debe tener su contrato marco CE- y todo proveedor debe existir
do $$ declare n int; begin
  select count(*) into n from stg_ce s where not exists (select 1 from contratos c where c.numero_interno='CE-'||s.cuenta); if n>0 then raise exception 'Hay % filas con cuenta sin contrato marco CE-', n; end if;
  select count(*) into n from stg_ce s where not exists (select 1 from proveedores p where p.razon_social=s.proveedor); if n>0 then raise exception 'Hay % filas con proveedor no dado de alta', n; end if;
end $$;

-- Liberar referencias SIN cascade hacia las facturas de Compra Emergente
update facturas set sustituida_por_id=null where sustituida_por_id in (select f.id from facturas f join capitulos c on c.id=f.capitulo_id where c.nombre='Compra Emergente');
update facturas set sustituye_a_id=null where sustituye_a_id in (select f.id from facturas f join capitulos c on c.id=f.capitulo_id where c.nombre='Compra Emergente');
do $$ begin if to_regclass('ooad_import_filas') is not null then
  update ooad_import_filas set matched_factura_id=null where matched_factura_id in (select f.id from facturas f join capitulos c on c.id=f.capitulo_id where c.nombre='Compra Emergente');
end if; end $$;

-- Borrar las facturas actuales de Compra Emergente (desglose/historial/validaciones caen en cascada)
delete from facturas f using capitulos c where f.capitulo_id=c.id and c.nombre='Compra Emergente';

-- Insertar las facturas de la cedula
with base as (
  select s.*, row_number() over (order by s.anio, s.mes, s.proveedor, s.folio) rn,
         p.id as proveedor_id, ct.id as contrato_id, ct.partida_id, pa.capitulo_id
  from stg_ce s
  join proveedores p on p.razon_social = s.proveedor
  join contratos ct on ct.numero_interno = 'CE-'||s.cuenta
  join partidas pa on pa.id = ct.partida_id
)
select 'HGZ2-CE-2026-'||lpad(rn::text,6,'0'), folio, capitulo_id, partida_id, contrato_id, proveedor_id,
       make_date(anio,mes,1), (make_date(anio,mes,1) + interval '1 month - 1 day')::date, mes_ej, anio_ej, 0.16, importe,
       gen::estatus_general, fir::estatus_firmas, ped::estatus_pedido_recepcion, oc, cr, pasivo
from base;

-- Verificacion
select c.nombre as capitulo, count(*) as facturas, to_char(sum(f.importe_factura),'FM999,999,999.00') as importe
from facturas f join capitulos c on c.id=f.capitulo_id where c.nombre='Compra Emergente' group by c.nombre;
select f.estatus_general, count(*) from facturas f join capitulos c on c.id=f.capitulo_id where c.nombre='Compra Emergente' group by f.estatus_general order by 2 desc;

commit;
